&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Strong Winds&lt;/strong&gt;&lt;span style="font-size:14pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Breezy to gusty winds return to the coast and Coast Range today, with a &lt;/span&gt;&lt;strong&gt;45&ndash;70% chance of gusts exceeding 45 mph&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;A stronger wind event is possible Wednesday, with a &lt;/span&gt;&lt;strong&gt;25&ndash;50% chance of major wind impacts&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;, including:&lt;/span&gt;&lt;strong&gt;45&ndash;58 mph gusts inland&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

