&lt;ul style="list-style-type:circle"&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;55&ndash;70 mph gusts along beaches and headlands&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
