&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Minor flooding will persist along the &lt;/span&gt;&lt;strong&gt;Pudding River at Aurora&lt;/strong&gt;&lt;span style="font-size:12pt"&gt; through today, though levels are trending downward.&amp;nbsp;&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Latest river forecasts:&lt;/strong&gt;&lt;span style="font-size:12pt"&gt; &lt;/span&gt;&lt;a class="Hyperlink SCXW232977702 BCX8" href="https://water.noaa.gov/" rel="noreferrer noopener" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; text-decoration-line: none;" target="_blank"&gt;&lt;span style="color:rgb(70, 120, 134); font-size:12pt"&gt;https://water.noaa.gov/&lt;/span&gt;&lt;/a&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;h2&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Safety Concerns Beyond the Weather&lt;/strong&gt;&lt;span style="font-size:18pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;h3&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Fallen Trees and Power Outages&lt;/strong&gt;&lt;span style="font-size:14pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Recent heavy rainfall has left soils saturated across western Oregon. Combined with strong winds, this increases the likelihood of &lt;/span&gt;&lt;strong&gt;downed trees and power lines&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;. Travelers should be prepared for:&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Sudden road blockages&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Localized outages&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Delays on major routes&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="color:rgb(33, 37, 41); font-size:12pt"&gt;Tree limbs can break without warning, especially in high winds or under the weight of snow and ice, so be extra cautious when walking outdoors.&lt;/span&gt;&lt;span style="color:rgb(33, 37, 41); font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Read more about power outage safety &lt;/strong&gt;&lt;a class="Hyperlink SCXW232977702 BCX8" href="https://apps.oregon.gov/oregon-newsroom/OR/OEM/Posts/Post/winter-power-outages" rel="noreferrer noopener" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; text-decoration-line: none;" target="_blank"&gt;&lt;strong&gt;here&lt;/strong&gt;&lt;/a&gt;&lt;span style="color:rgb(33, 37, 41); font-size:12pt"&gt;.&lt;/span&gt;&lt;span style="color:rgb(33, 37, 41); font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;h3&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Hazardous Water Conditions&lt;span style="font-size:14pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;OEM strongly advises the public to &lt;/span&gt;&lt;strong&gt;stay out of rivers, streams, and coastal waters&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;. As runoff from last week&rsquo;s atmospheric river continues moving through the system:&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Waterways contain &lt;/span&gt;&lt;strong&gt;high levels of debris&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;, including branches and logs&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;There is potential for &lt;/span&gt;&lt;strong&gt;sewage contamination&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Fastâ'moving, cold water increases the risk of injury or drowning&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;h2&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Travel Preparedness Guidance&lt;/strong&gt;&lt;span style="font-size:18pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;h3&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Check Conditions Before You Go&lt;span style="font-size:14pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Expect delays and allow extra travel time. Rushed drivers are unsafe drivers.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Fill up your gas tank. &lt;/strong&gt;&lt;span style="font-size:12pt"&gt;Be prepared for taking longer detours or remaining idle for an extended periods of time due to traffic jams by having plenty of gas in your tank.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Visit &lt;/span&gt;&lt;a class="Hyperlink SCXW232977702 BCX8" href="https://tripcheck.com/" rel="noreferrer noopener" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; text-decoration-line: none;" target="_blank"&gt;&lt;strong&gt;TripCheck.com&lt;/strong&gt;&lt;/a&gt;&lt;span style="font-size:12pt"&gt; or call &lt;/span&gt;&lt;strong&gt;511&lt;/strong&gt;&lt;span style="font-size:12pt"&gt; for realâ'time road conditions, chain requirements, and incident updates.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Make sure you &lt;/span&gt;&lt;strong&gt;have Wireless Emergency Alerts activated on your phone&lt;/strong&gt;&lt;span style="font-size:12pt"&gt; and are Signed up for emergency alerts for the area in Oregon you are visiting by going to &lt;/span&gt;&lt;a class="Hyperlink SCXW232977702 BCX8" href="https://oralert.gov/" rel="noreferrer noopener" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; text-decoration-line: none;" target="_blank"&gt;&lt;span style="color:rgb(70, 120, 134); font-size:12pt"&gt;ORAlert.gov&lt;/span&gt;&lt;/a&gt;&lt;span style="font-size:12pt"&gt; and typing in your destination&rsquo;s zip code.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;If you are visiting another state, search for that state&rsquo;s Department of Emergency Management and look for their instructions on how to receive alerts.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;If you end up stuck in snow, keep your car running as much as possible to stay warm, but &lt;/span&gt;&lt;strong&gt;keep the area around your exhaust pipe clear&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;h3&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Give Snowplows Space&lt;span style="font-size:14pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Never pass a snowplow&lt;/strong&gt;&lt;span style="font-size:12pt"&gt;.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Maintain a safe following distance&mdash;plows often create clouds of snow that reduce visibility.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Crews need room to operate safely; your patience helps keep everyone on the road safer.&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
